1338	
1339	function formatResourceIds(store: Store, ids: string[]): string {
1340	  return ids
1341	    .map((id) => {
1342	      const r = store.resources.find((x) => x.id === id);
1343	      return r ? `${id}（${r.name}）` : id;
1344	    })
1345	    .join('、');
1346	}
1347	
1348	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
1349	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1350	  const problems: string[] = [];
1351	  const seen = new Set<string>();
1352	  const dupes: string[] = [];
1353	  for (const id of rawIds) {
1354	    if (seen.has(id)) {
1355	      if (!dupes.includes(id)) dupes.push(id);
1356	    }
1357	    seen.add(id);
1358	  }
1359	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1360	
1361	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1362	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1363	
1364	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1365	  return [...seen].sort();
1366	}
1367	
1368	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
1369	  return mergeIntervals(
1370	    r.open.map(
1371	      ([s, e]) =>
1372	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
1373	    ),
1374	  );
1375	}
1376	
1377	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1378	function subtractSegments(
1379	  segments: Array<[number, number]>,
1380	  cuts: Array<[number, number]>,
1381	): Array<[number, number]> {
1382	  let result = segments;
1383	  for (const [cs, ce] of mergeIntervals(cuts)) {
1384	    const next: Array<[number, number]> = [];
1385	    for (const [s, e] of result) {
1386	      if (ce <= s || e <= cs) {
1387	        next.push([s, e]);
1388	        continue;
1389	      }
1390	      if (s < cs) next.push([s, cs]);
1391	      if (ce < e) next.push([ce, e]);
1392	    }
1393	    result = next;
1394	  }
1395	  return result;
1396	}
1397	
1398	// 某资源的有效停用记录（按开始时间、标识排序）
1399	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
1400	  return store.closures
1401	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
1402	    .sort(
1403	      (a, b) =>
1404	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
1405	        a.id.localeCompare(b.id),
1406	    );
1407	}
1408	
1409	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
1410	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
1411	  const cuts = activeClosuresOf(store, r.id).map(
1412	    (c) =>
1413	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
1414	  );
1415	  return subtractSegments(openSegmentsOf(r), cuts);
1416	}
1417	
1418	interface CoverageGap {
1419	  id: string;
1420	  r: ResourceRec;
1421	  closures: ClosureRec[]; // 与该区间重叠的相关有效停用（按开始时间、标识排序）
1422	}
1423	
1424	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
1425	function findCoverageGaps(
1426	  store: Store,
1427	  ids: string[],
1428	  startMin: number,
1429	  endMin: number,
1430	): CoverageGap[] {
1431	  const gaps: CoverageGap[] = [];
1432	  for (const id of ids) {
1433	    const r = store.resources.find((x) => x.id === id)!;
1434	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
1435	    const closures = activeClosuresOf(store, id).filter((c) => {
1436	      const cs = parseDateTime(c.start, '停用开始时间');
1437	      const ce = parseDateTime(c.end, '停用结束时间');
1438	      return cs < endMin && startMin < ce;
1439	    });
1440	    gaps.push({id, r, closures});
1441	  }
1442	  return gaps;
1443	}
1444	
1445	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1446	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1447	  const lines: string[] = [];
1448	  for (const g of gaps) {
1449	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1450	    for (const c of g.closures) {
1451	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1452	    }
1453	  }
1454	  return lines;
1455	}
1456	
1457	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
1458	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
1459	  const failing = findCoverageGaps(store, ids, startMin, endMin);
1460	  if (failing.length > 0) {
1461	    throw new BizError(
1462	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
1463	        gapLines(failing, '').join('\n'),
1464	    );
1465	  }
1466	}
1467	
1468	interface Conflict {
1469	  booking: BookingRec;
1470	  shared: string[];
1471	}
1472	
1473	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1474	function findConflicts(
1475	  store: Store,
1476	  ids: string[],
1477	  startMin: number,
1478	  endMin: number,
1479	  excludeBookingId?: string,
1480	): Conflict[] {
1481	  const wanted = new Set(ids);
1482	  const conflicts: Conflict[] = [];
1483	  for (const b of store.bookings) {
1484	    if (b.status !== 'active') continue;
1485	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1486	    const bStart = parseDateTime(b.start, '预约开始时间');
1487	    const bEnd = parseDateTime(b.end, '预约结束时间');
1488	    const overlap = bStart < endMin && startMin < bEnd;
1489	    if (!overlap) continue;
1490	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1491	    if (shared.length > 0) conflicts.push({booking: b, shared});
1492	  }
1493	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1494	  return conflicts;
1495	}
1496	
1497	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1498	  if (conflicts.length === 0) return;
1499	  const lines = conflicts.map(
1500	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1501	  );
1502	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1503	}
1504	
1505	// ---------------------------------------------------------------------------
1506	// 多项预约目标的统一批次校验（无写入副作用）
1507	//
1508	// 创建系列、批量改期、安全撤销与 iCalendar 导入共用本套逻辑，不再各自重复
1509	// 整批可行性循环。校验针对“全部目标生效后”的安排，统一三类检查：
1510	//   1) 实际可用覆盖：开放区间重叠或相接合并后扣除有效停用并集，须连续覆盖目标；
1511	//   2) 批外占用：批外有效预约（已取消不占用）与目标的共同资源时间重叠；
1512	//   3) 批内冲突：本批各目标彼此之间的共同资源时间重叠。
1513	// 区间一律左闭右开，端点相接可行；仅共同资源重叠才算冲突。
1514	// 本函数只读取数据与目标，绝不修改目标、业务记录或标识计数；
1515	// 全部失败项一次性收集（批内冲突在双方各自的失败项中都出现），
1516	// 诊断的业务定位（成员时间/预约标识/UID）与报告顺序由各入口负责。
1517	// ---------------------------------------------------------------------------
1518	
1519	interface ValidationTarget {
1520	  startMin: number;
1521	  endMin: number;
1522	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1523	}
1524	
1525	interface BatchTargetFailure {
1526	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1527	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1528	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1529	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1530	}
1531	
1532	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1533	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1534	function validateBatchTargets(
1535	  store: Store,
1536	  targets: ReadonlyArray<ValidationTarget>,
1537	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
