78	function addResource(
79	  df: string,
80	  name: string,
81	  open: Array<[string, string]> = OPEN_ALL,
82	  type = 'venue',
83	): void {
84	  const args = ['add-resource', '--type', type, '--name', name];
85	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
86	  ok(df, args, `登记资源 ${name}`);
87	}
88	
89	function findSlot(df: string, window: string, duration: string, groups: string[], ctx: string): CliResult {
90	  const args = ['find-slot', '--window', window, '--duration', duration];
91	  for (const g of groups) args.push('--group', g);
92	  return ok(df, args, ctx);
93	}
