99	function assertFileBytes(df: string, expected: Buffer, ctx: string): void {
100	  assert.ok(expected.equals(readFileSync(df)), `[${ctx}] 查询不得改动数据文件（逐字节比对）`);
101	}
102	
103	// 断言查询结果：起止时间与按需求组顺序的所选资源标识
104	function assertSlot(r: CliResult, start: string, end: string, picks: string[], ctx: string): void {
105	  assert.match(
106	    r.stdout,
107	    new RegExp(`最早可行时段: ${start} → ${end}`),
108	    `[${ctx}] 起止时间\nstdout:\n${r.stdout}`,
109	  );
110	  picks.forEach((id, i) => {
111	    assert.match(
112	      r.stdout,
113	      new RegExp(`第 ${i + 1} 组: ${id}（`),
114	      `[${ctx}] 第 ${i + 1} 组应选 ${id}\nstdout:\n${r.stdout}`,
115	    );
116	  });
117	}
118	
119	function assertNoSlot(r: CliResult, ctx: string): void {
120	  assert.match(r.stdout, /无解：窗口 /, `[${ctx}] 应明确提示无解\nstdout:\n${r.stdout}`);
121	  assert.ok(!r.stdout.includes('最早可行时段'), `[${ctx}] 无解不得给出时段\nstdout:\n${r.stdout}`);
122	}
